-- Source: National Mortgage Database (NMDB) Public Use File (7204 rows)
-- Generated by gen_mart_models.py
-- DEDUP (2026-08-11 verification): the landing load came from a runaway
-- generated pager that re-fetched the same content in a loop (19,054,246
-- rows, 11,648 real). Exact data rows are collapsed here so the mart is
-- correct even before the landing table itself is swapped clean.

with source as (
    select * from {{ source('ripple_raw', 'FED_FHFA_NMDB') }}
    qualify row_number() over (
        partition by GEO_TYPE, GEO_CODE, GEO_NAME, PERIOD_TYPE, PERIOD_VALUE,
                     DATASET_FAMILY, STATISTIC_NAME, STATISTIC_VALUE,
                     STATISTIC_UNIT, RELEASE_DATE
        order by _INGESTED_AT) = 1
)

-- DISTINCT (not just the landing-level qualify): raw formatting variants of
-- the same fact ("1.0" vs "1") collapse once the numeric/date casts apply,
-- so distinctness is enforced on the CAST values - 7,204 true rows.
select distinct
    GEO_TYPE as geo_type,
    GEO_CODE as geo_code,
    GEO_NAME as geo_name,
    PERIOD_TYPE as period_type,
    try_to_double(PERIOD_VALUE) as period_value,
    DATASET_FAMILY as dataset_family,
    STATISTIC_NAME as statistic_name,
    try_to_double(STATISTIC_VALUE) as statistic_value,
    STATISTIC_UNIT as statistic_unit,
    try_to_date(RELEASE_DATE) as release_date
from source
